/**
 * Sumber tunggal warna status BSTK.
 * DISAMAKAN dengan Document States (meta.states) doctype "BSTK". Dipakai untuk
 * pill status di list card portal. Selaras pola ttsStatus.js / deviasiStatus.js.
 */

// status → nama warna Frappe (persis dari Document States doctype "BSTK").
const STATE_COLOR = {
	Stok: 'cyan',
	'Belum Terpakai': 'orange',
	'Proses Verifikasi Dipakai': 'yellow',
	'Proses Verifikasi Rusak': 'yellow',
	'Proses Verifikasi Hilang': 'yellow',
	'Sudah Terpakai': 'green',
	Rusak: 'red',
	Hilang: 'gray',
	Cancelled: 'gray',
}

// Daftar status urut alur (stok → beredar → verifikasi → terminal).
export const STATUS_OPTIONS = Object.keys(STATE_COLOR)

// Tebak warna untuk status tak terdaftar — meniru frappe.utils.guess_colour.
function guessColor(status) {
	const s = String(status || '')
	// "Belum Terpakai" harus dinilai sebelum /Terpakai/, kalau tidak dokumen yang
	// masih beredar ikut terbaca hijau seolah sudah selesai.
	if (/Belum Terpakai|Pending|Proses|Menunggu|Review|Request/i.test(s)) return 'orange'
	if (/Reject|Rusak|Failed/i.test(s)) return 'red'
	if (/Terpakai|Dipakai|Approved|Done|Success/i.test(s)) return 'green'
	if (/Stok|Draft/i.test(s)) return 'cyan'
	return 'gray'
}

export function statusColor(status) {
	return STATE_COLOR[status] || guessColor(status)
}

// Pill (bg + teks) untuk badge status di card.
const PILL = {
	gray: 'bg-ui-surface-gray-100 text-ui-ink-gray-600',
	cyan: 'bg-ui-surface-cyan-100 text-ui-ink-cyan-700',
	blue: 'bg-ui-surface-blue-100 text-ui-ink-blue-700',
	orange: 'bg-ui-surface-orange-100 text-ui-ink-orange-700',
	yellow: 'bg-ui-surface-yellow-100 text-ui-ink-yellow-800',
	green: 'bg-ui-surface-green-100 text-ui-ink-green-700',
	red: 'bg-ui-surface-red-100 text-ui-ink-red-700',
}
export function statusPillClass(status) {
	return PILL[statusColor(status)] || PILL.gray
}

// Titik (border lingkaran) untuk picker status di sheet filter (dipakai nanti).
const DOT = {
	gray: 'border-ui-line-gray-400',
	cyan: 'border-ui-line-cyan-500',
	blue: 'border-ui-line-blue-500',
	orange: 'border-ui-line-orange-500',
	yellow: 'border-ui-line-yellow-500',
	green: 'border-ui-line-green-500',
	red: 'border-ui-line-red-500',
}
export function statusDotClass(status) {
	return DOT[statusColor(status)] || DOT.gray
}
